b'def format_bytes(n):
    """Format a number as human-readable bytes."""
    if n < 0:
        return "0 bytes"
    if n == 0:
        return "0 bytes"
    if n < 1024:
        return f"{n} bytes"
    elif n < 1048576:
        return f"{n // 1024} KB"
    elif n < 1073741824:
        return f"{n // 1048576} MB"
    elif n < 1099511627776:
        return f"{n // 1073741824} GB"
    else:
        return f"{n // 1099511627776} TB"'
